import { describe, it, expect } from "vitest";
import { readFileSync } from "fs";
import { join } from "path";
import {
  CORE_TOOL_NAMES,
  LEGACY_TEMPLATE_TOOL_NAMES,
  searchTools,
  type ToolDef,
} from "../src/tool-registry.js";

/**
 * CLAUDE.md / .cursorrules files generated by `init` before 0.11.0 instruct
 * the agent to call these four tools directly by their `mcp__contextforge__`
 * name. 0.11.0 hid them behind `cf_tools`, and `init` never rewrites a block
 * whose marker is already present — so every project initialised before
 * 0.11.0 kept telling the agent to call a tool its client could not see
 * ("No such tool available: mcp__contextforge__session_update"). The client
 * rejects the call before the server is involved, so the only fix that needs
 * nothing from the user is to list the tools again.
 *
 * This file pins that decision in both directions: the names stay core, and
 * the gateway keeps resolving them for files generated after 0.11.0, which
 * say `cf_tools` (query "update session") instead.
 */

const INDEX_SRC = readFileSync(join(__dirname, "..", "src", "index.ts"), "utf8");

/** Every tool declared in index.ts (same parser as tool-disclosure-guards). */
function declaredTools(): ToolDef[] {
  const start = INDEX_SRC.indexOf("const TOOLS");
  const open = INDEX_SRC.indexOf("[", start);
  let depth = 0;
  let block = "";
  for (let k = open; k < INDEX_SRC.length; k++) {
    if (INDEX_SRC[k] === "[") depth++;
    else if (INDEX_SRC[k] === "]") {
      depth--;
      if (depth === 0) {
        block = INDEX_SRC.slice(open, k + 1);
        break;
      }
    }
  }
  const marks = [...block.matchAll(/name:\s*"([a-z_]+)"/g)];
  return marks.map((m, i) => {
    const from = m.index!;
    const to = i + 1 < marks.length ? marks[i + 1].index! : block.length;
    const slice = block.slice(from, to);
    const desc = slice.match(/description:\s*\n?\s*"((?:[^"\\]|\\.)*)"/);
    return { name: m[1], description: desc ? desc[1] : "", inputSchema: {} };
  });
}

describe("tools named directly by pre-0.11.0 generated CLAUDE.md files", () => {
  it("are exactly the four the old templates emitted with the mcp__contextforge__ prefix", () => {
    expect([...LEGACY_TEMPLATE_TOOL_NAMES].sort()).toEqual([
      "memory_current_project",
      "memory_link_project",
      "memory_list_items",
      "session_update",
    ]);
  });

  it("stay in the visible core so those files work without re-running init", () => {
    for (const name of LEGACY_TEMPLATE_TOOL_NAMES) {
      expect(CORE_TOOL_NAMES, `${name} must stay core`).toContain(name);
    }
  });

  it("are real declared tools (guards against a rename leaving a dead core entry)", () => {
    const declared = new Set(declaredTools().map((t) => t.name));
    for (const name of LEGACY_TEMPLATE_TOOL_NAMES) {
      expect(declared.has(name), `${name} is not declared in src/index.ts`).toBe(true);
    }
  });
});

describe("cf_tools keeps resolving the legacy tools for post-0.11.0 templates", () => {
  it('finds session_update first for the generated instruction `cf_tools` (query "update session")', () => {
    const hits = searchTools(declaredTools(), "update session", 5);
    expect(hits[0]?.name).toBe("session_update");
  });

  it("searches and executes over every declared tool, not only the hidden ones", () => {
    // src/index.ts calls main() at import time, so the dispatch is checked as
    // text. Passing only `hidden` to the gateway would make a core tool
    // unreachable through cf_tools — exactly what the current templates rely on.
    expect(INDEX_SRC).not.toMatch(/searchTools\(\s*hidden\b/);
    expect(INDEX_SRC).not.toMatch(/hidden\.some\(\s*\(t\)\s*=>\s*t\.name === input\.name\)/);
  });

  it("still refuses to invoke itself", () => {
    expect(INDEX_SRC).toContain("cf_tools cannot invoke itself");
  });
});
